47	void mc_utf8_string_with_bad_char_destroy(mc_utf8_string_with_bad_char_t *utf8) {
48	    if (!utf8) {
49	        return;
50	    }
51	    bson_free(utf8->codepoint_offsets);
52	    _mongocrypt_buffer_cleanup(&utf8->buf);
53	    bson_free(utf8);
54	}
